/*
 * prog47_circular_queue.c
 *
 * Behaviour (as observed from the original binary):
 *
 *   * a fixed‑size circular queue of 5 elements (type long)
 *   * commands are supplied as command‑line arguments
 *   *   ENQ<number>   – enqueue the number
 *   *   D            – dequeue (remove) the front element
 *   *   F            – show the front element without removing it
 *   * any other argument or a malformed ENQ causes “ERR”
 *   * trying to enqueue when the queue is full prints “FULL”
 *   * trying to dequeue or read the front of an empty queue prints “EMPTY”
 *   * with no arguments the program prints “NOOP”
 *
 * The program prints the actions it performs, exactly matching the
 * strings found in the original binary.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define QUEUE_CAP 5

static long items[QUEUE_CAP];
static int  head  = 0;   /* index of the first element */
static int  count = 0;   /* number of elements currently stored */

/* ------------------------------------------------------------------ */
static void enqueue(long v)
{
    if (count >= QUEUE_CAP) {
        puts("FULL");
        return;
    }
    items[(head + count) % QUEUE_CAP] = v;
    ++count;
    printf("ENQ %ld\n", v);
}

/* ------------------------------------------------------------------ */
static void dequeue(void)
{
    if (count == 0) {
        puts("EMPTY");
        return;
    }
    long v = items[head];
    head = (head + 1) % QUEUE_CAP;
    --count;
    printf("DEQ %ld\n", v);
}

/* ------------------------------------------------------------------ */
static void front(void)
{
    if (count == 0) {
        puts("EMPTY");
        return;
    }
    printf("FRONT %ld\n", items[head]);
}

/* ------------------------------------------------------------------ */
int main(int argc, char **argv)
{
    if (argc < 2) {
        puts("NOOP");
        return 0;
    }

    for (int i = 1; i < argc; ++i) {
        char *arg = argv[i];

        if (arg[0] == 'E') {                     /* ENQ<number> */
            char *endptr;
            long v = strtol(arg + 1, &endptr, 10);
            if (*endptr != '\0') {               /* not a pure number */
                puts("ERR");
                continue;
            }
            enqueue(v);
        }
        else if (strcmp(arg, "D") == 0) {        /* DEQ */
            dequeue();
        }
        else if (strcmp(arg, "F") == 0) {        /* FRONT */
            front();
        }
        else {                                   /* unknown command */
            puts("ERR");
        }
    }
    return 0;
}
